    vat_id_valid?: boolean | null;
    /**
     * Vat Id Validation Error
     */
    vat_id_validation_error?: string | null;
    /**
     * Reverse Charge
     */
    reverse_charge: boolean;
    /**
     * Line Items
     */
    line_items: Array<VatPreviewLineItemSchema>;
    /**
     * Total Net
     */
