    seat_assignment_mode?: SeatAssignmentMode;
    /**
     * Max Tickets Per User
     */
    max_tickets_per_user?: number | null;
    /**
     * Venue Id
     */
    venue_id?: string | null;
    /**
     * Sector Id
     */
